/* UI-only fixtures are generated by tests/test_strategy.py, never written to site/. */
const assert = require('node:assert/strict');
const {spawn, spawnSync} = require('node:child_process');
const {chromium} = require('playwright');
const path = require('node:path');
const root = path.resolve(__dirname,'..');
const fixture = spawnSync('python3',['-c',`
import sys,json
from datetime import datetime
sys.path.insert(0,'tests')
from test_strategy import fixture,params
from screener.strategy import screen
bars=fixture()
r=screen({('TWSE','2330'):bars},bars[-1].date,params())
a=r['candidates'][0]
b=dict(a,market='TPEX',code='6488',name='<img src=x onerror=alert(1)>',score=a['score']-1,reward_risk=3.5)
r.update(schema_version=1,status='ok',as_of=bars[-1].date,generated_at=datetime.now().isoformat(),warnings=[],errors=[],candidates=[a,b])
print(json.dumps(r))
`],{cwd:root,encoding:'utf8'});
assert.equal(fixture.status,0,fixture.stderr);
const server = spawn('python3',['-m','http.server','8765','--bind','127.0.0.1','--directory','site'],{cwd:root,stdio:'ignore'});
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
(async()=>{
  let browser;
  try {
    for(let i=0;i<40;i++){
      try{const r=await fetch('http://127.0.0.1:8765/');if(r.ok)break;}catch{}
      if(i===39)throw Error('Static HTTP server did not start');
      await pause(100);
    }
    browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||(require('node:fs').existsSync('/usr/bin/chromium')?'/usr/bin/chromium':undefined),headless:true,args:['--no-sandbox']});
    const page=await browser.newPage({viewport:{width:1280,height:900}});
    const errors=[];page.on('pageerror',error=>errors.push(String(error)));
    // Validate the real snapshot first; fixtures are intercepted only afterwards.
    const snapshotResponse=await page.request.get('http://127.0.0.1:8765/results.json');
    assert.equal(snapshotResponse.ok(),true);
    const snapshot=await snapshotResponse.json();
    await page.goto('http://127.0.0.1:8765/');
    if(snapshot.status==='ok') {
      await page.waitForFunction(()=>document.querySelector('#as-of').textContent!=='—');
      assert.equal(await page.locator('.stock-card').count(),snapshot.candidates.length);
      assert.equal(await page.locator('#as-of').innerText(),snapshot.as_of);
    } else {
      await page.locator('#status.error').waitFor();
      assert.equal(await page.locator('.stock-card').count(),0);
    }
    if(snapshot.strategies){
      await page.locator('#strategy-select').selectOption('user_range_reclaim');
      assert.equal(await page.locator('.stock-card').count(),snapshot.strategies.user_range_reclaim.candidates.length);
      assert.match(await page.locator('#strategy-description').innerText(),/當天必須放量/);
      await page.locator('#strategy-select').selectOption(snapshot.active_model);
      assert.equal(await page.locator('.stock-card').count(),snapshot.candidates.length);
    }
    const realBacktest=await (await page.request.get('http://127.0.0.1:8765/backtest.json')).json();
    await page.locator('.research-card').first().waitFor();
    assert.equal(await page.locator('.research-card').count(),realBacktest.models.length);
    assert.match(await page.locator('#backtest-status').innerText(),/未還原權息/);
    assert.match(await page.locator('#backtest-detail h3').innerText(),/你的策略/);
    await page.locator('.research-card').nth(1).getByRole('button',{name:'查看進出場'}).click();
    assert.match(await page.locator('#backtest-detail h3').innerText(),/原策略/);
    if(realBacktest.models.every(m=>m.experiment)){
      assert.equal(await page.locator('.experiment').count(),4);
      assert.match(await page.locator('#research-protocol').innerText(),/不是真正未見/);
      await page.locator('.research-card').first().getByRole('button',{name:'查看改良版進出場',exact:true}).click();
      assert.match(await page.locator('#backtest-detail h3').innerText(),/改良候選/);
      assert.match(await page.locator('#backtest-detail').innerText(),/尚未取代/);
      await page.locator('.research-card').first().getByRole('button',{name:'查看進出場',exact:true}).click();
      const inconsistent=structuredClone(realBacktest);
      inconsistent.models[0].experiment.candidate.end='2099-01-01';
      await page.route('**/backtest.json',route=>route.fulfill({contentType:'application/json',body:JSON.stringify(inconsistent)}));
      await page.reload();await page.locator('#backtest-status.error').waitFor();
      assert.match(await page.locator('#backtest-status').innerText(),/期間不一致/);
      assert.equal(await page.locator('.research-card').count(),0);
      await page.unroute('**/backtest.json');await page.reload();await page.locator('.research-card').first().waitFor();
    }
    const manifestResponse=await page.request.get('http://127.0.0.1:8765/manifest.webmanifest');
    assert.equal(manifestResponse.ok(),true);
    const manifest=await manifestResponse.json();
    assert.equal(manifest.display,'standalone');
    assert.equal(manifest.start_url,'./');
    assert.equal((await page.request.get('http://127.0.0.1:8765/'+manifest.icons[0].src)).ok(),true);
    const unavailable={schema_version:1,status:'error',candidates:[],errors:['官方資料測試錯誤，未提供行情']};
    await page.route('**/results.json',route=>route.fulfill({contentType:'application/json',body:JSON.stringify(unavailable)}));
    await page.reload();await page.locator('#status.error').waitFor();
    assert.match(await page.locator('#status').innerText(),/官方資料測試錯誤/);
    assert.equal(await page.locator('.stock-card').count(),0);
    await page.unroute('**/results.json');
    await page.route('**/results.json',route=>route.fulfill({contentType:'application/json',body:fixture.stdout}));
    await page.reload();await page.locator('.stock-card').first().waitFor();
    assert.equal(await page.locator('.stock-card').count(),2);
    assert.equal(await page.locator('.chart svg').count(),2);
    assert.equal(await page.locator('.stock-card img').count(),0,'stock names must be text, not HTML');
    assert.ok(await page.locator('rect[fill="#cb4242"]').count()>0,'Taiwan up candles must be red');
    // The rising-only open/close fixture uses red bodies; force one green candle to test rendering too.
    const mixed=JSON.parse(fixture.stdout);mixed.candidates[0].bars[20].open=mixed.candidates[0].bars[20].close+.1;
    await page.unroute('**/results.json');
    await page.route('**/results.json',route=>route.fulfill({contentType:'application/json',body:JSON.stringify(mixed)}));
    await page.reload();await page.locator('.stock-card').first().waitFor();
    assert.ok(await page.locator('rect[fill="#178367"]').count()>0,'Taiwan down candles must be green');
    await page.getByRole('button',{name:'上櫃',exact:true}).click();
    assert.equal(await page.locator('.stock-card').count(),1);
    assert.match(await page.locator('.stock-card').innerText(),/6488/);
    await page.getByRole('button',{name:'全部市場',exact:true}).click();
    await page.locator('#sort').selectOption('reward_risk');
    assert.match(await page.locator('.stock-card').first().innerText(),/6488/);
    await page.locator('#search').fill('2330');assert.equal(await page.locator('.stock-card').count(),1);
    await page.locator('#search').fill('找不到');assert.equal(await page.locator('.stock-card').count(),0);
    assert.equal(await page.locator('#empty').isVisible(),true);
    await page.locator('#search').fill('');
    await page.locator('.parameters summary').click();
    assert.equal(await page.locator('.parameter-table tr').count(),20);
    await page.screenshot({path:'/tmp/taiwan-stock-desktop.png',fullPage:true});
    await page.setViewportSize({width:390,height:844});
    assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth),true,'mobile page must not overflow');
    await page.screenshot({path:'/tmp/taiwan-stock-mobile.png',fullPage:true});
    // A failed network response must remove all candidates.
    await page.unroute('**/results.json');
    await page.route('**/results.json',route=>route.fulfill({status:503,body:'unavailable'}));
    await page.reload();await page.locator('#status.error').waitFor();
    assert.match(await page.locator('#status').innerText(),/HTTP 503/);
    assert.equal(await page.locator('.stock-card').count(),0);
    await page.route('**/backtest.json',route=>route.fulfill({status:503,body:'unavailable'}));
    await page.reload();await page.locator('#backtest-status.error').waitFor();
    assert.match(await page.locator('#backtest-status').innerText(),/HTTP 503/);
    assert.equal(await page.locator('.research-card').count(),0);
    assert.deepEqual(errors,[]);
    console.log('PASS browser: independent user strategy, four research models, trade records, real snapshot, charts, filters, mobile layout and source/report errors');
  } finally {if(browser)await browser.close();server.kill();}
})().catch(error=>{console.error(error);process.exitCode=1;});
